<template><section class="triage-page">
  <header class="triage-header"><div><div class="eyebrow">ON-CALL / WDF4</div><h1>Operational triage</h1><p>Find impact first, then follow evidence to the failing layer</p></div><div class="segments"><button v-for="tab in tabs" :key="tab" :class="{active:activeTab===tab}" @click="activeTab=tab">{{ tab }}</button></div></header>
  <div v-if="activeTab!=='Open'" class="empty-state"><strong>No {{ activeTab.toLowerCase() }} incidents</strong><span>Incident state is read-only in this console.</span></div>
  <section v-if="finding && activeTab==='Open'" class="incident-banner">
    <div class="incident-severity">DEGRADED</div><div class="incident-main"><h2>{{ finding.title }}</h2><p>{{ finding.message }}</p></div><div class="incident-stat"><span>Scope</span><strong>{{ finding.scope }}</strong><small>observed snapshot</small></div><div class="incident-stat"><span>Confidence</span><strong>{{ finding.confidence }}</strong><small>evidence-derived</small></div><router-link :to="finding.to" class="investigate">Investigate <span>→</span></router-link>
  </section>
  <div v-if="activeTab==='Open'" class="triage-grid">
    <section class="panel impact"><h2>Potential impact path</h2><p>Impact is separated from correlation</p><div class="impact-row"><div><strong>Central IronCore API</strong><span>live condition</span></div><b class="healthy">{{ centralHealthy ? 'Healthy' : 'Unknown' }}</b></div><div class="impact-row"><div><strong>Zone provider layer</strong><span>{{ degradedZones }} visibility gap(s)</span></div><b :class="degradedZones?'degraded':'healthy'">{{ degradedZones?'Degraded':'Healthy' }}</b></div><div class="impact-row"><div><strong>MachinePools</strong><span>no current failure asserted</span></div><b>{{ machinePools }} observed</b></div><div class="impact-row"><div><strong>Affected Shoots</strong><span>no impact claimed without a proven edge</span></div><b class="unknown">Unknown</b></div><footer>No user impact claimed without an authoritative relationship.</footer></section>
    <section class="panel freshness"><h2>Collector freshness</h2><p>Missing data never becomes green</p><div v-for="source in collectorRows" :key="source.id" class="freshness-row"><span>{{ source.label }}</span><strong>{{ source.age }}</strong><b :class="source.state">{{ source.value }}</b></div></section>
  </div>
  <section class="panel fleet"><div class="fleet-heading"><div><h2>Fleet health</h2><p>Click any count to inspect the exact filtered set</p></div><div class="segments segments--small"><button class="active">All environments</button><button>Canary</button><button>Dev</button></div></div><div class="fleet-table"><div class="fleet-row fleet-row--head"><span>Layer</span><span>Healthy</span><span>Degraded</span><span>Unknown</span><span>Freshness</span><span>Next investigation</span></div><div v-for="row in fleetRows" :key="row.layer" class="fleet-row"><strong>{{ row.layer }}</strong><span>{{ row.healthy }}</span><span class="degraded">{{ row.degraded }}</span><span class="unknown">{{ row.unknown }}</span><span>{{ row.freshness }}</span><router-link :to="row.to">Inspect →</router-link></div></div></section>
</section></template>
<script setup lang="ts">
import { computed,ref } from 'vue'
import { useSreLandscapeStore } from '@/stores/sre/landscape'
import { useSreStatusStore } from '@/stores/sre/status'
const landscape=useSreLandscapeStore(),status=useSreStatusStore()
const tabs=['Open','Acknowledged','History'],activeTab=ref('Open')
const centralHealthy=computed(()=>status.sources.filter(s=>s.id.includes('ironcore')&&!s.id.includes('gardener')).every(s=>s.access==='ok'))
const degradedSources=computed(()=>status.sources.filter(s=>s.access!=='ok'||s.freshness!=='fresh'))
const degradedZones=computed(()=>degradedSources.value.filter(s=>/^wdf4/.test(s.id)).length)
const machinePools=computed(()=>landscape.summary['machine-pool']??0)
const finding=computed(()=>{const observation=landscape.observations[0];if(observation)return{title:observation.reason||'Operational finding',message:observation.message,scope:observation.related?.[0]||'WDF4',confidence:observation.confidence||'derived',to:'/sre/dependencies/'+encodeURIComponent(observation.related?.[0]||'')};const source=degradedSources.value[0];return source?{title:`${source.id} collection gap`,message:`The source is ${source.access} and currently reports ${source.freshness} data. Available evidence remains visible, but impact cannot be fully established.`,scope:source.id,confidence:'observed',to:'/sre/sources'}:null})
function age(value?:string){if(!value)return'—';const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));return seconds<60?`${seconds}s`:`${Math.floor(seconds/60)}m`}
const sourceLabel=(id:string)=>id.replace(/-/g,' ').replace(/\b\w/g,(c:string)=>c.toUpperCase())
const collectorRows=computed(()=>status.sources.slice(0,5).map(s=>({id:s.id,label:sourceLabel(s.id),age:age(s.collectedAt),state:s.access==='ok'?'live':'unknown',value:s.access==='ok'?'live':s.access})))
const fleetRows=computed(()=>[{layer:'Central APIs',healthy:status.sources.filter(s=>s.id.includes('ironcore')&&s.access==='ok').length,degraded:status.sources.filter(s=>s.id.includes('ironcore')&&s.access!=='ok').length,unknown:0,freshness:status.freshness,to:'/sre/sources'},{layer:'Zonal CAPI',healthy:status.sources.filter(s=>/^wdf4/.test(s.id)&&s.access==='ok').length,degraded:degradedZones.value,unknown:0,freshness:status.freshness,to:'/sre/zones'},{layer:'Workloads',healthy:landscape.summary['ironcore-vm']??0,degraded:landscape.observations.length,unknown:0,freshness:status.freshness,to:'/sre/vms'}])
</script>
